"""Merge two total-time dictionaries by adding the amount of collected time
    in each hierarchical element.

    Parameters
    ----------
    a, b : total-time dict
        A total-time dict is a dictionary with the keys being the name of the
        timer and the value being a pair of a total time number and a
        dictionary further splitting up the time into lower hierarchical
        components.

    Returns
    -------
    total-time dict
    """
def merge_total_time_dict(a: Any, b: Any) -> object {
    all_keys = `set(a).union(`set(b));
    total = `dict();
    for key in all_keys {
        (t_a, d_a) = a.get(key, (0, `dict()));
        (t_b, d_b) = b.get(key, (0, `dict()));
        total[key] = ((t_a + t_b), merge_total_time_dict(d_a, d_b));
    }
    return total;
}

"""_around_mean.

    Args:
        prmsl:
        i:
        j:
    """
def _around_mean(prmsl: Any, i: int, j: int) -> object {
    sum_data = 0;
    for i in range(-1, 2, 1) {
        for j in range(-1, 2, 1) {
            if ((i == 0) and (j == 0)) {
                continue;
            }
            sum_data += prmsl[(i + i)][(j + i)];
        }
    }
    return (sum_data / 8);
}

"""
    Calculate the final degrees plato based on attenuation and original plato.
    """
def attenuation_to_final_plato(attenuation: float, original_plato: float) -> object {
    apparent_attenuation = attenuation / 0.81;
    return (original_plato - (original_plato * apparent_attenuation));
}

"""
    Normalizes a normal python list.
    Probably works with numpy arrays too.
    """
def normalize_arr(arr: Any) -> object {
    total = sum(arr);
    if (total == 0) {
        print("Arr is empty/All numbers are zero, returning [1], This is a warning");
        return [1];
    }
    return [(i / total) for i in arr];
}

